            for(const auto& effect:actor.kit.effects){if(std::none_of(combat.effects.begin(),combat.effects.end(),[&](const auto& known){return known->id==effect->id;}))combat.effects.push_back(effect);if(effect->reaction&&effect->reaction->motion&&!combat.clips.contains(effect->reaction->motion->clip.id)){auto clip=load_cooked_clip(registry,cas,effect->reaction->motion->clip.id);combat.clips.emplace(clip.definition.id,std::make_shared<const AnimationClip>(clip.definition,clip.archive));}}
