            require(actor.kit.attributes.id==cooked.attributes.id&&actor.kit.attributes.generation==cooked.attributes.generation&&bool(actor.kit.tags)==bool(cooked.tags)&&(!cooked.tags||actor.kit.tags->generation==cooked.tags->generation),"A spawned NPC's kit must share the Play kit's attribute schema and tag registry");
            for(const auto& ability:actor.kit.abilities){if(std::none_of(combat.abilities.begin(),combat.abilities.end(),[&](const auto& known){return known->id==ability->id;}))combat.abilities.push_back(ability);else require(std::any_of(combat.abilities.begin(),combat.abilities.end(),[&](const auto& known){return known->id==ability->id&&known->generation==ability->generation;}),"Player and NPC disagree on a shared ability generation");require(ability->action->motion.has_value(),"Combat action needs a frozen clip");if(!combat.clips.contains(ability->action->motion->clip.id)){auto clip=load_cooked_clip(registry,cas,ability->action->motion->clip.id);combat.clips.emplace(clip.definition.id,std::make_shared<const AnimationClip>(clip.definition,clip.archive));}}
